import{_ as t,o,c as a,ag as d}from"./chunks/framework.DC2M1AAK.js";const u=JSON.parse('{"title":"The client protocol","description":"","frontmatter":{},"headers":[],"relativePath":"components/client-protocol.md","filePath":"components/client-protocol.md"}'),c={name:"components/client-protocol.md"};function s(i,e,n,r,l,p){return o(),a("div",null,[...e[0]||(e[0]=[d(`<h1 id="the-client-protocol" tabindex="-1">The client protocol <a class="header-anchor" href="#the-client-protocol" aria-label="Permalink to &quot;The client protocol&quot;">​</a></h1><p>Everything a client (the widget, a web view, a native app) needs. The widget in <code>packages/widget</code> implements all of it; a native client implements the same calls.</p><h2 id="authentication" tabindex="-1">Authentication <a class="header-anchor" href="#authentication" aria-label="Permalink to &quot;Authentication&quot;">​</a></h2><ul><li>Every <code>/api/*</code> call except <code>/api/health</code> and <code>/api/auth/exchange</code> carries <code>Authorization: Bearer &amp;lt;token&gt;</code> when login is on. The token is either an <strong>agent token</strong> from <code>POST /api/auth/exchange</code> (preferred — docs/SDK-AUTH.md) or your upstream token, verified strictly. 401 <code>login_required</code> / <code>token_expired</code>, 503 <code>auth_unavailable</code>.</li><li>Optional embed gating: <code>X-Agent-Key: &lt;gateway key&gt;</code>.</li></ul><h2 id="endpoints" tabindex="-1">Endpoints <a class="header-anchor" href="#endpoints" aria-label="Permalink to &quot;Endpoints&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Method &amp; path</th><th>Purpose</th></tr></thead><tbody><tr><td><code>POST /api/session</code></td><td>Create a chat → <code>{session_id, nudge, brand}</code>. Store the id (localStorage) to resume.</td></tr><tr><td><code>POST /api/chat</code></td><td>One turn, JSON: <code>{session_id, message, display?}</code> → <code>AgentReply</code></td></tr><tr><td><code>POST /api/chat/stream</code></td><td>The same turn as Server-Sent Events (below)</td></tr><tr><td><code>POST /api/chat/voice</code></td><td>Raw audio in (<code>Content-Type: audio/*</code>, <code>X-Agent-Session</code>), SSE out starting with <code>transcript</code></td></tr><tr><td><code>POST /api/transcribe</code></td><td>Transcription only</td></tr><tr><td><code>GET /api/session/:id/history</code></td><td>Resume: <code>{entries:[{role,text,ui}], completion, preview, completed, usage, media, nudge}</code>. 410 ⇒ start fresh.</td></tr><tr><td><code>GET /api/session/:id/events</code></td><td>Long-lived SSE for server-initiated events (<code>ready</code>, <code>nudge</code>, heartbeats)</td></tr><tr><td><code>GET /api/session/:id/usage</code></td><td>Token usage and cap standings (percentages)</td></tr><tr><td><code>GET /api/my/sessions</code></td><td>The caller&#39;s chats (metadata + a short preview)</td></tr><tr><td><code>DELETE /api/session/:id</code></td><td>Delete a chat (owner)</td></tr><tr><td><code>POST / GET / PATCH / DELETE /api/media</code></td><td>Upload one file (raw body, <code>X-Agent-Session</code>, <code>X-Agent-Filename</code>), list, arrange (<code>{order, labels, cover}</code>), remove (<code>?key=</code>)</td></tr><tr><td><code>GET /api/health</code></td><td>Readiness + configuration summary (no secrets)</td></tr><tr><td><code>GET /widget.js</code></td><td>The embeddable client</td></tr></tbody></table><h2 id="stream-events-api-chat-stream" tabindex="-1">Stream events (<code>/api/chat/stream</code>) <a class="header-anchor" href="#stream-events-api-chat-stream" aria-label="Permalink to &quot;Stream events (\`/api/chat/stream\`)&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>event: transcript  data: {text, language, confidence, duration_s}   (voice only, first)</span></span>
<span class="line"><span>event: delta       data: {text}                                      prose, word by word; ui fences never stream</span></span>
<span class="line"><span>event: tool        data: {name}                                      a tool started (show a status line)</span></span>
<span class="line"><span>event: preview     data: PreviewState                                the draft: slots, missing, state, defaults, steps…</span></span>
<span class="line"><span>event: done        data: {reply, ui, tool_trace, domain, kind?, completion?, usage}</span></span>
<span class="line"><span>event: error       data: {error, error_id?, degraded?}</span></span></code></pre></div><p><code>kind</code> names the runtime step that answered a turn without a model call. <code>completion</code> ends the chat: render the end-state card (<code>label</code>, <code>entity_url</code> only when present), freeze the composer, keep uploads welcome.</p><h2 id="ui-blocks" tabindex="-1">ui blocks <a class="header-anchor" href="#ui-blocks" aria-label="Permalink to &quot;ui blocks&quot;">​</a></h2><p>A reply&#39;s <code>ui</code> is an array of blocks (types in <code>@marg-adk/types</code>). Tapping an option sends its <code>value</code> as the user&#39;s next message; a form submit sends <code>&quot;Label [key]: value; …&quot;</code> plus a readable <code>display</code>. Block families:</p><ul><li><code>chips</code> (single pick; <code>ghost</code>, <code>sel</code>, <code>disabled</code>, <code>limit</code>), <code>multichips</code> (<code>min</code>, <code>max</code>, <code>submit</code>, <code>own {max}</code>, <code>page</code>, <code>skip</code>), <code>list</code> (rows with <code>title</code>/<code>subtitle</code>/<code>value</code>).</li><li><code>card</code> (<code>title</code>, <code>fields [{label, value, source}]</code>, <code>actions</code>, <code>sections</code> — the review&#39;s per-section edit chips). The runtime&#39;s summary card carries <code>confirm: true</code>.</li><li><code>form</code> (<code>rows [{key, label, kind: pick|multi|text|num|area, options, value, required, hint, source, unit, error, say}]</code>, <code>submit</code>, <code>echo</code>, <code>skip</code>). Required rows gate the submit; an option&#39;s <code>fills</code> sets other rows.</li><li><code>toggles</code> (<code>options [{label, value, on}]</code>, <code>hint</code>, <code>wire {prefix, none}</code>).</li><li><code>link</code> (<code>label</code>, <code>url</code> — http/https or your app&#39;s scheme only).</li><li>Runtime-only: <code>table</code>, <code>progress</code>, <code>media</code>, <code>bars</code>.</li><li>Every block may carry <code>step: &quot;&lt;key&gt;&quot;</code> — which runtime step drew it (evals and clients key on it).</li></ul><h2 id="resume-nudges-completion" tabindex="-1">Resume, nudges, completion <a class="header-anchor" href="#resume-nudges-completion" aria-label="Permalink to &quot;Resume, nudges, completion&quot;">​</a></h2><ul><li>Store the session id; on load call <code>/history</code> and replay <code>entries</code>; the last assistant entry carries the open ask&#39;s block again, so the user can answer after a refresh.</li><li>Open <code>/events</code> to receive nudges live; they are also persisted into the transcript.</li><li>A finished chat answers 409 to a new turn; &quot;start another&quot; = a new session.</li></ul><h2 id="media" tabindex="-1">Media <a class="header-anchor" href="#media" aria-label="Permalink to &quot;Media&quot;">​</a></h2><p>Upload immediately (one request per file, raw bytes); the gateway holds keys on the session, attaches them the instant the write returns an id, and keeps accepting uploads after completion. <code>GET /api/media</code> → <code>{file_base, items:[{key, kind, url?, filename, label?, cover, attached}], attached_to}</code>; an image loads from <code>file_base + &quot;/&quot; + key</code> when no <code>url</code> is given.</p><h2 id="voice" tabindex="-1">Voice <a class="header-anchor" href="#voice" aria-label="Permalink to &quot;Voice&quot;">​</a></h2><p>Record a note, POST the bytes; the stream opens with <code>transcript</code>, then the normal events. The note IS the message (no edit step); STT runs server-side so keys never reach the client.</p><h2 id="errors" tabindex="-1">Errors <a class="header-anchor" href="#errors" aria-label="Permalink to &quot;Errors&quot;">​</a></h2><p><code>{error, code?, error_id?}</code>. Codes: <code>login_required</code>, <code>token_expired</code>, <code>auth_unavailable</code>, <code>rate_limit</code> (with <code>Retry-After</code>), <code>usage_cap</code> (<code>scope</code>, <code>percent</code>, <code>resets_in_s</code>), <code>completed</code>. Unknown-session text is exact (&quot;Unknown session — call /api/session first.&quot;) — clients key their recovery on it.</p><hr><p><small>Source: <a href="https://github.com/marg-adk/marg/blob/main/docs/CLIENT-PROTOCOL.md">docs/CLIENT-PROTOCOL.md</a> — edit it there; the site mirrors the repository.</small></p>`,22)])])}const m=t(c,[["render",s]]);export{u as __pageData,m as default};
